def ar1_forecast(x=None, phi=None, mu=None, h=None, sigma2=None):
    """AR(1) forecast towards the mean. The h-step forecast mu + phi^h (x_n - mu) of a stationary AR(1) with mean mu, and (when the innovation variance is given) its forecast error variance and 95 % prediction interval.
    Formula: \\hat x_{n+h} = \\mu + \\phi^h(x_n - \\mu),\\ \\operatorname{Var} = \\sigma^2\\frac{1-\\phi^{2h}}{1-\\phi^2}
    Inputs:
        x: the last observed value x_n
        phi: AR coefficient, |phi| < 1
        mu: the process mean
        h: forecast horizon (default 1) (optional)
        sigma2: innovation variance (optional, for the interval) (optional)
    Outputs: forecast (mu + phi^h (x_n - mu)), variance (sigma^2 (1 - phi^(2h)) / (1 - phi^2)), lower (lower 95 % limit), upper (upper 95 % limit)
    See also: help("ar1_forecast")
    """
    given = {k: v for k, v in dict(x=x, phi=phi, mu=mu, h=h, sigma2=sigma2).items() if v is not None}
    return _P.solve("ar1_forecast", **given)

def ar1_properties(phi=None, sigma2=None, k=None, c=None):
    """Mean, variance and autocorrelation of an AR(1) process. For a stationary AR(1) x_t = c + phi x_{t-1} + e_t: the mean c/(1 - phi), the variance sigma^2/(1 - phi^2), and the lag-k autocorrelation phi^k and autocovariance.
    Formula: \\mu = \\frac{c}{1-\\phi},\\ \\gamma_0 = \\frac{\\sigma^2}{1-\\phi^2},\\ \\rho_k = \\phi^k
    Inputs:
        phi: AR coefficient, |phi| < 1
        sigma2: innovation variance sigma^2
        k: the lag k (default 1) (optional)
        c: the constant c (default 0) (optional)
    Outputs: mean (c / (1 - phi)), variance (sigma^2 / (1 - phi^2)), acf_k (phi^k), acov_k (variance x phi^k)
    See also: help("ar1_properties")
    """
    given = {k: v for k, v in dict(phi=phi, sigma2=sigma2, k=k, c=c).items() if v is not None}
    return _P.solve("ar1_properties", **given)

def ar2_stationarity(phi1=None, phi2=None):
    """Stationarity of an AR(2) process. Whether x_t = phi1 x_{t-1} + phi2 x_{t-2} + e_t is stationary: the largest modulus of the inverse characteristic roots (roots of z^2 - phi1 z - phi2) must be below 1.
    Formula: z^2 - \\phi_1 z - \\phi_2 = 0,\\quad \\text{stationary} \\iff \\max|z_i| < 1
    Inputs:
        phi1: phi_1
        phi2: phi_2
    Outputs: stationary (yes or no), max_modulus (largest modulus of the inverse roots), roots (real or complex)
    See also: help("ar2_stationarity")
    """
    given = {k: v for k, v in dict(phi1=phi1, phi2=phi2).items() if v is not None}
    return _P.solve("ar2_stationarity", **given)

