def arma11_theoretical_acf(phi=None, theta=None, K=None):
    """Theoretical autocorrelations of an ARMA(1,1) process. The autocorrelations rho_1..rho_K of x_t = phi x_{t-1} + e_t + theta e_{t-1}.
    Formula: \\rho_1 = \\frac{(1+\\phi\\theta)(\\phi+\\theta)}{1+2\\phi\\theta+\\theta^2},\\ \\rho_k = \\phi\\,\\rho_{k-1}
    Inputs:
        phi: AR coefficient, |phi| < 1
        theta: MA coefficient (plus-sign convention)
        K: number of lags (default 5) (optional)
    Outputs: acf (rho_1..rho_K), rho1 (rho_1)
    See also: help("arma11_theoretical_acf")
    """
